package com.hunllefed;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ExpectedValueAnalyticsTest
{
	private static final double EPSILON = 0.000_001;

	@Test
	public void lethalChanceUsesAccuracyAndInclusiveDamageRolls()
	{
		DamageEstimate attack = new DamageEstimate(0.5, 10);

		// Five of the eleven accurate damage rolls (6..10) are lethal.
		assertEquals(
			5.0 / 22.0,
			LethalChanceCalculator.singleAttackChance(attack, 6),
			EPSILON);
		assertEquals(0.0, LethalChanceCalculator.singleAttackChance(attack, 11), 0.0);
	}

	@Test
	public void cumulativeLethalChanceUsesComplementOfSurvival()
	{
		PerformanceStatistics stats = new PerformanceStatistics();
		stats.reset();
		DamageEstimate attack = new DamageEstimate(0.5, 10);
		double singleChance = 5.0 / 22.0;

		stats.addLethalOpportunity(attack, 6);
		stats.addLethalOpportunity(attack, 6);

		assertEquals(2, stats.lethalOpportunities);
		assertEquals(1.0 - Math.pow(1.0 - singleChance, 2), stats.getLethalChance(), EPSILON);
	}

	@Test
	public void playerExpectedKillTimeClampsSuccessfulZeroDamageToOne()
	{
		double ticks = KillTimeCalculator.expectedKillTicks(
			1,
			Collections.singletonList(
				new AttackSample(new DamageEstimate(1.0, 2, true), 4)));

		// Accurate rolls 0, 1 and 2 become damage 1, 1 and 2.
		assertEquals(4.0, ticks, EPSILON);
	}

	@Test
	public void npcExpectedKillTimeRetainsSuccessfulZeroDamage()
	{
		double ticks = KillTimeCalculator.expectedKillTicks(
			1,
			Collections.singletonList(
				new AttackSample(new DamageEstimate(1.0, 2), 4)));

		// NPC accurate rolls remain 0, 1 and 2, so E[attacks] is 1.5.
		assertEquals(6.0, ticks, EPSILON);
	}

	@Test
	public void expectedKillTimeRepeatsObservedAttackCycleWithoutLostTicks()
	{
		double ticks = KillTimeCalculator.expectedKillTicks(
			1,
			Arrays.asList(
				new AttackSample(DamageEstimate.blocked(), 4),
				new AttackSample(new DamageEstimate(0.5, 2, true), 5)));

		// First live roll is at tick 8. Accuracy misses add a nine-tick cycle;
		// E[time] = 8 + (1/2)/(1/2) * 9 = 17 ticks.
		assertEquals(17.0, ticks, EPSILON);
	}

	@Test
	public void performanceExpectedKillTimePreservesObservedAttackGaps()
	{
		DamageEstimate attack = new DamageEstimate(0.5, 1, true);
		double ticks = KillTimeCalculator.performanceExpectedKillTicks(
			1,
			Arrays.asList(
				new AttackSample(attack, 4, 6),
				new AttackSample(attack, 4, 12)));

		// Every attack has a 50% kill chance. The observed six-tick cadence
		// therefore produces an expected kill on the second attack at tick 12.
		assertEquals(12.0, ticks, EPSILON);
		assertEquals(
			8.0,
			KillTimeCalculator.expectedKillTicks(
				1,
				Arrays.asList(
					new AttackSample(attack, 4, 6),
					new AttackSample(attack, 4, 12))),
			EPSILON);
	}

	@Test
	public void expectedKillTimeIsUnavailableWithoutDamage()
	{
		assertTrue(Double.isNaN(KillTimeCalculator.expectedKillTicks(
			1000,
			Collections.singletonList(new AttackSample(DamageEstimate.blocked(), 4)))));
	}

	@Test
	public void corruptedHitpointDistributionConverges()
	{
		double ticks = KillTimeCalculator.expectedKillTicks(
			1000,
			Collections.singletonList(
				new AttackSample(new DamageEstimate(0.72, 40, true), 4)));

		assertTrue(Double.isFinite(ticks));
		assertTrue(ticks > 250.0);
		assertTrue(ticks < 350.0);
	}

	@Test
	public void difficultiesExposeCorrectBossHitpoints()
	{
		assertEquals(600, GauntletDifficulty.CRYSTALLINE.getHitpoints());
		assertEquals(1000, GauntletDifficulty.CORRUPTED.getHitpoints());
	}

	@Test
	public void fishEquivalentAccountsForStartingAndEndingHitpoints()
	{
		PerformanceStatistics stats = new PerformanceStatistics();
		stats.reset();
		stats.startingHitpoints = 99;
		stats.endingHitpoints = 19;
		stats.damageTaken = 100;
		stats.expectedDamageTaken = 110;
		stats.expectedDamageTakenWithoutAvoidableHits = 90;

		assertEquals(1.0, stats.getActualFishEquivalent(), EPSILON);
		assertEquals(0.5, stats.getFishEquivalentWithoutAvoidableHits(), EPSILON);
		assertEquals(1.5, stats.getObservedMechanicsExpectedFishEquivalent(), EPSILON);
		assertEquals(1.0, stats.getAvoidableHitHealingFishEquivalent(), EPSILON);
	}

	@Test
	public void unusedStartingHitpointsCanCoverAllDamage()
	{
		PerformanceStatistics stats = new PerformanceStatistics();
		stats.reset();
		stats.startingHitpoints = 99;
		stats.endingHitpoints = 39;
		stats.damageTaken = 60;
		stats.expectedDamageTaken = 40;
		stats.expectedDamageTakenWithoutAvoidableHits = 40;

		assertEquals(0.0, stats.getActualFishEquivalent(), EPSILON);
		assertEquals(0.0, stats.getFishEquivalentWithoutAvoidableHits(), EPSILON);
		assertEquals(0.0, stats.getAvoidableHitHealingFishEquivalent(), EPSILON);
	}
}

package com.hunllefed;

import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class CombatCalculatorTest
{
	private static final double EPSILON = 0.000_001;

	@Test
	public void normalAccuracyFormulaHandlesBothBranches()
	{
		assertEquals(1.0 - 52.0 / 202.0, CombatCalculator.hitChance(100, 50), EPSILON);
		assertEquals(50.0 / 202.0, CombatCalculator.hitChance(50, 100), EPSILON);
	}

	@Test
	public void perfectedStaffUsesFixedBaseHitAndAuguryDamage()
	{
		EquipmentSnapshot equipment = EquipmentSnapshot.fromItemIds(
			ItemID.GAUNTLET_MAGIC_T3_HM,
			ItemID.GAUNTLET_MAGIC_T3_HM,
			ItemID.GAUNTLET_HELMET_T1_HM,
			ItemID.GAUNTLET_CHESTPLATE_T1_HM,
			ItemID.GAUNTLET_PLATELEGS_T1_HM);

		DamageEstimate estimate = CombatCalculator.playerAttack(
			CombatStyle.MAGIC,
			99,
			99,
			equipment.getAttackBonus(CombatStyle.MAGIC, MeleeType.CRUSH),
			0,
			2,
			0,
			1.25,
			1.0,
			equipment.getMagicMaxHit(),
			40,
			false);

		int attackRoll = 134 * (200 + 64);
		int defenceRoll = 249 * 84;
		assertEquals(40, estimate.getMaxHit());
		assertEquals(CombatCalculator.hitChance(attackRoll, defenceRoll),
			estimate.getHitChance(), EPSILON);
		assertEquals(
			estimate.getHitChance() * (20.0 + 1.0 / 41.0),
			estimate.getExpectedDamage(),
			EPSILON);
	}

	@Test
	public void perfectedBowRapidUsesRangedLevelAndStrengthPrayer()
	{
		EquipmentSnapshot equipment = EquipmentSnapshot.fromItemIds(
			ItemID.GAUNTLET_RANGED_T3_HM,
			ItemID.GAUNTLET_RANGED_T3_HM,
			ItemID.GAUNTLET_HELMET_T1_HM,
			ItemID.GAUNTLET_CHESTPLATE_T1_HM,
			ItemID.GAUNTLET_PLATELEGS_T1_HM);

		DamageEstimate estimate = CombatCalculator.playerAttack(
			CombatStyle.RANGED,
			99,
			99,
			equipment.getAttackBonus(CombatStyle.RANGED, MeleeType.CRUSH),
			equipment.getStrengthBonus(CombatStyle.RANGED),
			0,
			0,
			1.20,
			1.23,
			0,
			0,
			false);

		assertEquals(41, estimate.getMaxHit());
		assertEquals(
			CombatCalculator.hitChance(126 * 252, 249 * 84),
			estimate.getHitChance(),
			EPSILON);
	}

	@Test
	public void hunllefMagicAttackUsesPlayerMagicAndDefenceRoll()
	{
		EquipmentSnapshot equipment = EquipmentSnapshot.fromItemIds(
			ItemID.GAUNTLET_MAGIC_T3_HM,
			ItemID.GAUNTLET_MAGIC_T3_HM,
			ItemID.GAUNTLET_HELMET_T2_HM,
			ItemID.GAUNTLET_CHESTPLATE_T2_HM,
			ItemID.GAUNTLET_PLATELEGS_T2_HM);

		DamageEstimate protectedEstimate = CombatCalculator.hunllefAttack(
			GauntletDifficulty.CORRUPTED,
			CombatStyle.MAGIC,
			99,
			99,
			equipment.getDefenceBonus(CombatStyle.MAGIC),
			0,
			1.25,
			1.25,
			true,
			equipment.getArmourTierSum());

		assertEquals(224, equipment.getDefenceBonus(CombatStyle.MAGIC));
		assertEquals(6, equipment.getArmourTierSum());
		assertEquals(10, protectedEstimate.getMaxHit());
		assertEquals(
			CombatCalculator.hitChance(249 * 154, 130 * 288),
			protectedEstimate.getHitChance(),
			EPSILON);

		DamageEstimate unprotectedEstimate = CombatCalculator.hunllefAttack(
			GauntletDifficulty.CORRUPTED,
			CombatStyle.MAGIC,
			99,
			99,
			equipment.getDefenceBonus(CombatStyle.MAGIC),
			0,
			1.25,
			1.25,
			false,
			equipment.getArmourTierSum());
		assertEquals(68, unprotectedEstimate.getMaxHit());
	}

	@Test
	public void hunllefProtectionAndTornadoCapsUseArmourTierSum()
	{
		assertEquals(16, GauntletDifficulty.CORRUPTED.getProtectedMaxHit(0));
		assertEquals(13, GauntletDifficulty.CORRUPTED.getProtectedMaxHit(3));
		assertEquals(10, GauntletDifficulty.CORRUPTED.getProtectedMaxHit(6));
		assertEquals(8, GauntletDifficulty.CORRUPTED.getProtectedMaxHit(9));
		assertEquals(19.5, GauntletDifficulty.CORRUPTED.getTornadoExpectedDamage(3), EPSILON);
		assertEquals(15.0, GauntletDifficulty.CORRUPTED.getTornadoExpectedDamage(6), EPSILON);

		assertEquals(12, GauntletDifficulty.CRYSTALLINE.getProtectedMaxHit(0));
		assertEquals(6, GauntletDifficulty.CRYSTALLINE.getProtectedMaxHit(9));
		assertEquals(7.5, GauntletDifficulty.CRYSTALLINE.getTornadoExpectedDamage(9), EPSILON);
	}

	@Test
	public void protectedPlayerAttackHasZeroExpectedDamage()
	{
		DamageEstimate estimate = CombatCalculator.playerAttack(
			CombatStyle.RANGED,
			99,
			99,
			188,
			138,
			0,
			0,
			1.20,
			1.23,
			0,
			0,
			true);

		assertEquals(0, estimate.getMaxHit());
		assertEquals(0.0, estimate.getExpectedDamage(), EPSILON);
	}

	@Test
	public void attackSpeedAccountsForBowStyleAndSceptre()
	{
		EquipmentSnapshot bow = EquipmentSnapshot.fromItemIds(ItemID.GAUNTLET_RANGED_T3_HM);
		assertEquals(5, bow.getAttackSpeed(0));
		assertEquals(4, bow.getAttackSpeed(1));
		assertEquals(5, bow.getAttackSpeed(3));

		EquipmentSnapshot sceptre = EquipmentSnapshot.fromItemIds(ItemID.GAUNTLET_SCEPTRE);
		assertEquals(5, sceptre.getAttackSpeed(0));
	}
}

