package com.hunllefed;

final class CombatCalculator
{
	static final int HUNLLEF_DEFENCE_LEVEL = 240;
	static final int HUNLLEF_DEFENCE_BONUS = 20;
	static final int FLOOR_MIN_HIT = 10;
	static final int FLOOR_MAX_HIT = 20;

	private CombatCalculator()
	{
	}

	static DamageEstimate playerAttack(
		CombatStyle style,
		int accuracyLevel,
		int damageLevel,
		int attackBonus,
		int strengthBonus,
		int accuracyStanceBonus,
		int strengthStanceBonus,
		double accuracyPrayer,
		double strengthPrayer,
		int fixedMagicMaxHit,
		int magicDamagePermille,
		boolean protectedByHunllef)
	{
		if (protectedByHunllef)
		{
			return DamageEstimate.blocked();
		}

		int effectiveAccuracy;
		int maxHit;

		switch (style)
		{
			case MELEE:
				effectiveAccuracy = scaleLevel(accuracyLevel, accuracyPrayer)
					+ 8 + accuracyStanceBonus;
				int effectiveStrength = scaleLevel(damageLevel, strengthPrayer)
					+ 8 + strengthStanceBonus;
				maxHit = maxHit(effectiveStrength, strengthBonus);
				break;
			case RANGED:
				effectiveAccuracy = scaleLevel(accuracyLevel, accuracyPrayer)
					+ 8 + accuracyStanceBonus;
				int effectiveRangedStrength = scaleLevel(damageLevel, strengthPrayer)
					+ 8 + strengthStanceBonus;
				maxHit = maxHit(effectiveRangedStrength, strengthBonus);
				break;
			case MAGIC:
				if (fixedMagicMaxHit <= 0)
				{
					return DamageEstimate.blocked();
				}
				effectiveAccuracy = scaleLevel(accuracyLevel, accuracyPrayer)
					+ 9 + accuracyStanceBonus;
				maxHit = fixedMagicMaxHit
					+ (fixedMagicMaxHit * magicDamagePermille / 1000);
				break;
			default:
				throw new IllegalArgumentException("Unsupported combat style: " + style);
		}

		int attackRoll = effectiveAccuracy * (attackBonus + 64);
		int defenceRoll = (HUNLLEF_DEFENCE_LEVEL + 9) * (HUNLLEF_DEFENCE_BONUS + 64);
		return new DamageEstimate(
			hitChance(attackRoll, defenceRoll),
			maxHit,
			true);
	}

	static DamageEstimate hunllefAttack(
		GauntletDifficulty difficulty,
		CombatStyle style,
		int defenceLevel,
		int magicLevel,
		int defenceBonus,
		int defensiveStanceBonus,
		double defencePrayer,
		double magicDefencePrayer,
		boolean correctProtectionPrayer,
		int armourTierSum)
	{
		int effectiveDefence = scaleLevel(defenceLevel, defencePrayer);
		if (style == CombatStyle.MAGIC)
		{
			int effectiveMagic = scaleLevel(magicLevel, magicDefencePrayer);
			effectiveDefence = effectiveMagic * 7 / 10 + effectiveDefence * 3 / 10;
		}

		effectiveDefence += defensiveStanceBonus;
		int defenceRoll = (effectiveDefence + 8) * (defenceBonus + 64);
		int attackRoll = (HUNLLEF_DEFENCE_LEVEL + 9) * (difficulty.getAttackBonus() + 64);
		int maxHit = correctProtectionPrayer
			? difficulty.getProtectedMaxHit(armourTierSum)
			: difficulty.getUnprotectedMaxHit();

		return new DamageEstimate(hitChance(attackRoll, defenceRoll), maxHit);
	}

	static double stompExpectedDamage(GauntletDifficulty difficulty)
	{
		return stompAttack(difficulty).getExpectedDamage();
	}

	static DamageEstimate stompAttack(GauntletDifficulty difficulty)
	{
		return new DamageEstimate(1.0, difficulty.getUnprotectedMaxHit());
	}

	static double floorExpectedDamage()
	{
		return (FLOOR_MIN_HIT + FLOOR_MAX_HIT) / 2.0;
	}

	static double hitChance(int attackRoll, int defenceRoll)
	{
		if (attackRoll > defenceRoll)
		{
			return 1.0 - (defenceRoll + 2.0) / (2.0 * (attackRoll + 1.0));
		}
		return attackRoll / (2.0 * (defenceRoll + 1.0));
	}

	private static int scaleLevel(int level, double multiplier)
	{
		return (int) Math.floor(level * multiplier);
	}

	private static int maxHit(int effectiveStrength, int strengthBonus)
	{
		return (effectiveStrength * (strengthBonus + 64) + 320) / 640;
	}

}

package com.hunllefed;

final class DamageEstimate
{
	private final double hitChance;
	private final int maxHit;
	private final double expectedDamage;
	private final boolean clampsSuccessfulZero;

	DamageEstimate(double hitChance, int maxHit)
	{
		this(hitChance, maxHit, false);
	}

	DamageEstimate(double hitChance, int maxHit, boolean clampsSuccessfulZero)
	{
		this.hitChance = hitChance;
		this.maxHit = maxHit;
		this.clampsSuccessfulZero = clampsSuccessfulZero;
		double averageAccurateHit = maxHit / 2.0;
		if (clampsSuccessfulZero && maxHit > 0)
		{
			averageAccurateHit += 1.0 / (maxHit + 1);
		}
		this.expectedDamage = hitChance * averageAccurateHit;
	}

	static DamageEstimate blocked()
	{
		return new DamageEstimate(0.0, 0);
	}

	double getHitChance()
	{
		return hitChance;
	}

	int getMaxHit()
	{
		return maxHit;
	}

	double getExpectedDamage()
	{
		return expectedDamage;
	}

	boolean clampsSuccessfulZero()
	{
		return clampsSuccessfulZero;
	}
}

package com.hunllefed;

enum GauntletDifficulty
{
	CRYSTALLINE(600, 76, 50, new int[]{12, 10, 8, 6}, new int[][]{
		{10, 20},
		{10, 16},
		{7, 13},
		{5, 10}
	}),
	CORRUPTED(1000, 90, 68, new int[]{16, 13, 10, 8}, new int[][]{
		{15, 30},
		{14, 25},
		{10, 20},
		{8, 15}
	});

	private final int hitpoints;
	private final int attackBonus;
	private final int unprotectedMaxHit;
	private final int[] protectedMaxHits;
	private final int[][] tornadoRanges;

	GauntletDifficulty(
		int hitpoints,
		int attackBonus,
		int unprotectedMaxHit,
		int[] protectedMaxHits,
		int[][] tornadoRanges)
	{
		this.hitpoints = hitpoints;
		this.attackBonus = attackBonus;
		this.unprotectedMaxHit = unprotectedMaxHit;
		this.protectedMaxHits = protectedMaxHits;
		this.tornadoRanges = tornadoRanges;
	}

	int getHitpoints()
	{
		return hitpoints;
	}

	int getAttackBonus()
	{
		return attackBonus;
	}

	int getUnprotectedMaxHit()
	{
		return unprotectedMaxHit;
	}

	int getProtectedMaxHit(int armourTierSum)
	{
		return protectedMaxHits[damageReductionTier(armourTierSum)];
	}

	double getTornadoExpectedDamage(int armourTierSum)
	{
		int[] range = tornadoRanges[damageReductionTier(armourTierSum)];
		return (range[0] + range[1]) / 2.0;
	}

	private static int damageReductionTier(int armourTierSum)
	{
		if (armourTierSum >= 9)
		{
			return 3;
		}
		if (armourTierSum >= 6)
		{
			return 2;
		}
		if (armourTierSum >= 3)
		{
			return 1;
		}
		return 0;
	}
}

package com.hunllefed;

import net.runelite.api.Client;
import net.runelite.api.Prayer;

final class PrayerModifiers
{
	private final double accuracy;
	private final double strength;
	private final int magicDamagePermille;
	private final double defence;
	private final double magicDefence;

	private PrayerModifiers(
		double accuracy,
		double strength,
		int magicDamagePermille,
		double defence,
		double magicDefence)
	{
		this.accuracy = accuracy;
		this.strength = strength;
		this.magicDamagePermille = magicDamagePermille;
		this.defence = defence;
		this.magicDefence = magicDefence;
	}

	static PrayerModifiers capture(Client client, CombatStyle style)
	{
		double accuracy = 1.0;
		double strength = 1.0;
		int magicDamagePermille = 0;

		switch (style)
		{
			case MELEE:
				if (active(client, Prayer.PIETY))
				{
					accuracy = 1.20;
					strength = 1.23;
				}
				else if (active(client, Prayer.CHIVALRY))
				{
					accuracy = 1.15;
					strength = 1.18;
				}
				else
				{
					accuracy = meleeAccuracy(client);
					strength = meleeStrength(client);
				}
				break;
			case RANGED:
				if (active(client, Prayer.RIGOUR))
				{
					accuracy = 1.20;
					strength = 1.23;
				}
				else if (active(client, Prayer.DEADEYE))
				{
					accuracy = 1.18;
					strength = 1.18;
				}
				else if (active(client, Prayer.EAGLE_EYE))
				{
					accuracy = 1.15;
					strength = 1.15;
				}
				else if (active(client, Prayer.HAWK_EYE))
				{
					accuracy = 1.10;
					strength = 1.10;
				}
				else if (active(client, Prayer.SHARP_EYE))
				{
					accuracy = 1.05;
					strength = 1.05;
				}
				break;
			case MAGIC:
				if (active(client, Prayer.AUGURY))
				{
					accuracy = 1.25;
					magicDamagePermille = 40;
				}
				else if (active(client, Prayer.MYSTIC_VIGOUR))
				{
					accuracy = 1.18;
					magicDamagePermille = 30;
				}
				else if (active(client, Prayer.MYSTIC_MIGHT))
				{
					accuracy = 1.15;
					magicDamagePermille = 20;
				}
				else if (active(client, Prayer.MYSTIC_LORE))
				{
					accuracy = 1.10;
					magicDamagePermille = 10;
				}
				else if (active(client, Prayer.MYSTIC_WILL))
				{
					accuracy = 1.05;
				}
				break;
			default:
				break;
		}

		return new PrayerModifiers(
			accuracy,
			strength,
			magicDamagePermille,
			defence(client),
			magicDefence(client));
	}

	double getAccuracy()
	{
		return accuracy;
	}

	double getStrength()
	{
		return strength;
	}

	int getMagicDamagePermille()
	{
		return magicDamagePermille;
	}

	double getDefence()
	{
		return defence;
	}

	double getMagicDefence()
	{
		return magicDefence;
	}

	private static double meleeAccuracy(Client client)
	{
		if (active(client, Prayer.INCREDIBLE_REFLEXES))
		{
			return 1.15;
		}
		if (active(client, Prayer.IMPROVED_REFLEXES))
		{
			return 1.10;
		}
		if (active(client, Prayer.CLARITY_OF_THOUGHT))
		{
			return 1.05;
		}
		return 1.0;
	}

	private static double meleeStrength(Client client)
	{
		if (active(client, Prayer.ULTIMATE_STRENGTH))
		{
			return 1.15;
		}
		if (active(client, Prayer.SUPERHUMAN_STRENGTH))
		{
			return 1.10;
		}
		if (active(client, Prayer.BURST_OF_STRENGTH))
		{
			return 1.05;
		}
		return 1.0;
	}

	private static double defence(Client client)
	{
		if (active(client, Prayer.PIETY)
			|| active(client, Prayer.RIGOUR)
			|| active(client, Prayer.AUGURY))
		{
			return 1.25;
		}
		if (active(client, Prayer.CHIVALRY))
		{
			return 1.20;
		}
		if (active(client, Prayer.STEEL_SKIN))
		{
			return 1.15;
		}
		if (active(client, Prayer.ROCK_SKIN))
		{
			return 1.10;
		}
		if (active(client, Prayer.DEADEYE)
			|| active(client, Prayer.MYSTIC_VIGOUR)
			|| active(client, Prayer.THICK_SKIN))
		{
			return 1.05;
		}
		return 1.0;
	}

	private static double magicDefence(Client client)
	{
		if (active(client, Prayer.AUGURY))
		{
			return 1.25;
		}
		if (active(client, Prayer.MYSTIC_VIGOUR))
		{
			return 1.18;
		}
		if (active(client, Prayer.MYSTIC_MIGHT))
		{
			return 1.15;
		}
		if (active(client, Prayer.MYSTIC_LORE))
		{
			return 1.10;
		}
		if (active(client, Prayer.MYSTIC_WILL))
		{
			return 1.05;
		}
		return 1.0;
	}

	private static boolean active(Client client, Prayer prayer)
	{
		return client.getVarbitValue(prayer.getVarbit()) == 1;
	}
}

package com.hunllefed;

import java.util.ArrayList;
import java.util.List;

final class PerformanceStatistics
{
	private static final int PADDLEFISH_HEAL = 20;

	private final List<AttackSample> playerAttackCycle = new ArrayList<>();

	int totalTicks;
	int modelledPlayerAttacks;
	int unmodelledPlayerAttacks;
	int damageDealt;
	int damageTaken;
	int startingHitpoints;
	int endingHitpoints;
	int lethalOpportunities;
	double expectedDamageDealt;
	double expectedDamageTaken;
	double expectedDamageTakenWithoutAvoidableHits;
	double lethalSurvivalProbability;
	double performanceExpectedKillTicks;
	double noLossExpectedKillTicks;
	boolean hunllefDefeated;

	void reset()
	{
		playerAttackCycle.clear();
		totalTicks = 0;
		modelledPlayerAttacks = 0;
		unmodelledPlayerAttacks = 0;
		damageDealt = 0;
		damageTaken = 0;
		startingHitpoints = 0;
		endingHitpoints = 0;
		lethalOpportunities = 0;
		expectedDamageDealt = 0;
		expectedDamageTaken = 0;
		expectedDamageTakenWithoutAvoidableHits = 0;
		lethalSurvivalProbability = 1.0;
		performanceExpectedKillTicks = Double.NaN;
		noLossExpectedKillTicks = Double.NaN;
		hunllefDefeated = false;
	}

	void addPlayerAttack(DamageEstimate estimate, int attackSpeed, int elapsedTick)
	{
		playerAttackCycle.add(new AttackSample(estimate, attackSpeed, elapsedTick));
		expectedDamageDealt += estimate.getExpectedDamage();
		modelledPlayerAttacks++;
	}

	void addLethalOpportunity(DamageEstimate estimate, int hitpoints)
	{
		double probability = LethalChanceCalculator.singleAttackChance(estimate, hitpoints);
		if (probability <= 0.0)
		{
			return;
		}

		lethalOpportunities++;
		lethalSurvivalProbability *= 1.0 - probability;
	}

	void finish(GauntletDifficulty difficulty)
	{
		performanceExpectedKillTicks = KillTimeCalculator.performanceExpectedKillTicks(
			difficulty.getHitpoints(),
			playerAttackCycle);
		noLossExpectedKillTicks = KillTimeCalculator.expectedKillTicks(
			difficulty.getHitpoints(),
			playerAttackCycle);
	}

	double getLethalChance()
	{
		return 1.0 - lethalSurvivalProbability;
	}

	double getActualKillTicks()
	{
		return hunllefDefeated ? totalTicks : Double.NaN;
	}

	double getDamageDealtDifference()
	{
		return damageDealt - expectedDamageDealt;
	}

	double getDamageTakenDifference()
	{
		return damageTaken - expectedDamageTaken;
	}

	double getActualFishEquivalent()
	{
		return fishEquivalent(damageTaken, startingHitpoints, endingHitpoints);
	}

	double getFishEquivalentWithoutAvoidableHits()
	{
		return fishEquivalent(
			expectedDamageTakenWithoutAvoidableHits,
			startingHitpoints,
			endingHitpoints);
	}

	double getObservedMechanicsExpectedFishEquivalent()
	{
		return fishEquivalent(
			expectedDamageTaken,
			startingHitpoints,
			endingHitpoints);
	}

	double getAvoidableHitHealingFishEquivalent()
	{
		return Math.max(
			0.0,
			getObservedMechanicsExpectedFishEquivalent()
				- getFishEquivalentWithoutAvoidableHits());
	}

	private static double fishEquivalent(
		double damage,
		int startingHitpoints,
		int endingHitpoints)
	{
		double healingRequired = damage + endingHitpoints - startingHitpoints;
		return Math.max(0.0, healingRequired) / PADDLEFISH_HEAL;
	}
}

