package com.hunllefed;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class HunllefExpectedDamageOverlay extends OverlayPanel
{
	private static final Color GOOD = new Color(0x66, 0xCC, 0x66);
	private static final Color BAD = new Color(0xFF, 0x66, 0x66);
	private static final Color NEUTRAL = Color.LIGHT_GRAY;

	private final HunllefExpectedDamagePlugin plugin;
	private final HunllefExpectedDamageConfig config;

	@Inject
	private HunllefExpectedDamageOverlay(
		HunllefExpectedDamagePlugin plugin,
		HunllefExpectedDamageConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panelComponent.setPreferredSize(new Dimension(270, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.isBossActive())
		{
			if (config.hideOverlayDuringFight())
			{
				return null;
			}
			renderLive(plugin.getStatistics());
			return super.render(graphics);
		}

		if (!plugin.shouldShowResults())
		{
			return null;
		}

		renderResults(plugin.getStatistics());
		return super.render(graphics);
	}

	private void renderLive(PerformanceStatistics stats)
	{
		addTitle("Hunllef analysis");
		addDamageLine("Damage dealt", stats.damageDealt, stats.expectedDamageDealt, true);
		addDamageLine("Damage taken", stats.damageTaken, stats.expectedDamageTaken, false);
		addLine("Lethal opportunities", Integer.toString(stats.lethalOpportunities), NEUTRAL);
		addLine("Death chance", percent(stats.getLethalChance()), riskColor(stats));
	}

	private void renderResults(PerformanceStatistics stats)
	{
		addTitle("Hunllef analysis");
		addLine("Damage: actual / expected", "", NEUTRAL);
		addDamageLine("Damage dealt", stats.damageDealt, stats.expectedDamageDealt, true);
		addDamageLine("Damage taken", stats.damageTaken, stats.expectedDamageTaken, false);
		addLine("Kill time", "", NEUTRAL);
		addKillTimeLines(stats);

		if (config.showFishAnalysis())
		{
			addLine("Food check (20 HP each)", "", NEUTRAL);
			addLine(
				"HP: start / end",
				stats.startingHitpoints + " / " + stats.endingHitpoints,
				NEUTRAL);
			addLine(
				"Needed this fight",
				format(stats.getActualFishEquivalent()),
				NEUTRAL);
			addLine(
				"Expected without avoidable hits",
				format(stats.getFishEquivalentWithoutAvoidableHits()),
				NEUTRAL);
			addLine(
				"Healing from avoidable hits",
				format(stats.getAvoidableHitHealingFishEquivalent()),
				avoidableHitHealingColor(stats.getAvoidableHitHealingFishEquivalent()));
		}

		addLine("Lethal opportunities", Integer.toString(stats.lethalOpportunities), NEUTRAL);
		addLine("Death chance", percent(stats.getLethalChance()), riskColor(stats));

		if (stats.unmodelledPlayerAttacks > 0)
		{
			int observedAttacks = stats.modelledPlayerAttacks + stats.unmodelledPlayerAttacks;
			addLine(
				"Damage model coverage",
				stats.modelledPlayerAttacks + " / " + observedAttacks + " attacks",
				Color.ORANGE);
		}
	}

	private void addKillTimeLines(PerformanceStatistics stats)
	{
		double actualTicks = stats.getActualKillTicks();
		addLine(
			"Actual",
			Double.isFinite(actualTicks) ? formatTime(actualTicks) : "DNF",
			Double.isFinite(actualTicks) ? NEUTRAL : BAD);
		addExpectedTimeLine("Performance EV", stats.performanceExpectedKillTicks);
		addExpectedTimeLine("No-loss EV", stats.noLossExpectedKillTicks);
	}

	private void addExpectedTimeLine(String label, double ticks)
	{
		addLine(
			label,
			Double.isFinite(ticks) ? formatTime(ticks) : "n/a",
			Double.isFinite(ticks) ? NEUTRAL : Color.ORANGE);
	}

	private void addDamageLine(String label, int actual, double expected, boolean higherIsBetter)
	{
		double difference = actual - expected;
		Color color;
		if (Math.abs(difference) < 0.05)
		{
			color = NEUTRAL;
		}
		else
		{
			boolean good = higherIsBetter ? difference > 0 : difference < 0;
			color = good ? GOOD : BAD;
		}

		addLine(
			label,
			actual + " / " + format(expected) + " (" + signed(difference) + ")",
			color);
	}

	private void addTitle(String title)
	{
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(title)
			.color(Color.WHITE)
			.build());
	}

	private void addLine(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build());
	}

	private static Color riskColor(PerformanceStatistics stats)
	{
		return stats.lethalOpportunities == 0 ? GOOD : Color.ORANGE;
	}

	private static Color avoidableHitHealingColor(double fishEquivalent)
	{
		return fishEquivalent < 0.05 ? GOOD : BAD;
	}

	private static String formatTime(double ticks)
	{
		double totalSeconds = ticks * 0.6;
		int minutes = (int) (totalSeconds / 60.0);
		double seconds = totalSeconds - minutes * 60.0;
		return String.format(Locale.ROOT, "%d:%04.1f", minutes, seconds);
	}

	private static String percent(double probability)
	{
		return format(probability * 100.0) + "%";
	}

	private static String format(double value)
	{
		return String.format(Locale.ROOT, "%.1f", value);
	}

	private static String signed(double value)
	{
		return String.format(Locale.ROOT, "%+.1f", value);
	}
}

package com.hunllefed;

import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;

final class EquipmentSnapshot
{
	private static final int NO_WEAPON = -1;

	private int stabAttack;
	private int slashAttack;
	private int crushAttack;
	private int magicAttack;
	private int rangedAttack;
	private int meleeStrength;
	private int rangedStrength;
	private int magicDefence;
	private int rangedDefence;
	private int armourTierSum;
	private int weaponId = NO_WEAPON;

	static EquipmentSnapshot capture(Client client)
	{
		EquipmentSnapshot snapshot = new EquipmentSnapshot();
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return snapshot;
		}

		Item[] items = equipment.getItems();
		int weaponSlot = EquipmentInventorySlot.WEAPON.getSlotIdx();
		for (int slot = 0; slot < items.length; slot++)
		{
			Item item = items[slot];
			if (item == null || item.getId() <= 0)
			{
				continue;
			}

			if (slot == weaponSlot)
			{
				snapshot.weaponId = item.getId();
			}

			snapshot.add(statsFor(item.getId()));
		}
		return snapshot;
	}

	static EquipmentSnapshot fromItemIds(int weaponId, int... itemIds)
	{
		EquipmentSnapshot snapshot = new EquipmentSnapshot();
		snapshot.weaponId = weaponId;
		for (int itemId : itemIds)
		{
			snapshot.add(statsFor(itemId));
		}
		return snapshot;
	}

	int getAttackBonus(CombatStyle style, MeleeType meleeType)
	{
		switch (style)
		{
			case MELEE:
				switch (meleeType)
				{
					case STAB:
						return stabAttack;
					case SLASH:
						return slashAttack;
					case CRUSH:
					default:
						return crushAttack;
				}
			case RANGED:
				return rangedAttack;
			case MAGIC:
				return magicAttack;
			default:
				return 0;
		}
	}

	int getStrengthBonus(CombatStyle style)
	{
		return style == CombatStyle.RANGED ? rangedStrength : meleeStrength;
	}

	int getDefenceBonus(CombatStyle style)
	{
		return style == CombatStyle.MAGIC ? magicDefence : rangedDefence;
	}

	int getArmourTierSum()
	{
		return armourTierSum;
	}

	int getWeaponId()
	{
		return weaponId;
	}

	int getMagicMaxHit()
	{
		switch (weaponId)
		{
			case ItemID.GAUNTLET_MAGIC_T1:
			case ItemID.GAUNTLET_MAGIC_T1_HM:
				return 23;
			case ItemID.GAUNTLET_MAGIC_T2:
			case ItemID.GAUNTLET_MAGIC_T2_HM:
				return 31;
			case ItemID.GAUNTLET_MAGIC_T3:
			case ItemID.GAUNTLET_MAGIC_T3_HM:
				return 39;
			default:
				return 0;
		}
	}

	int getAttackSpeed(int stance)
	{
		if (isRangedWeapon(weaponId))
		{
			// Gauntlet bows have a base speed of 5; Rapid (style index 1) is 4.
			return stance == 1 ? 4 : 5;
		}
		return isSceptre() ? 5 : 4;
	}

	boolean supports(CombatStyle style)
	{
		switch (style)
		{
			case MAGIC:
				return getMagicMaxHit() > 0;
			case RANGED:
				return isRangedWeapon(weaponId);
			case MELEE:
				return weaponId == NO_WEAPON
					|| weaponId == ItemID.GAUNTLET_SCEPTRE
					|| isMeleeWeapon(weaponId);
			default:
				return false;
		}
	}

	boolean isSceptre()
	{
		return weaponId == ItemID.GAUNTLET_SCEPTRE;
	}

	boolean isHalberd()
	{
		return isMeleeWeapon(weaponId);
	}

	private void add(ItemCombatStats stats)
	{
		stabAttack += stats.stabAttack;
		slashAttack += stats.slashAttack;
		crushAttack += stats.crushAttack;
		magicAttack += stats.magicAttack;
		rangedAttack += stats.rangedAttack;
		meleeStrength += stats.meleeStrength;
		rangedStrength += stats.rangedStrength;
		magicDefence += stats.magicDefence;
		rangedDefence += stats.rangedDefence;
		armourTierSum += stats.armourTier;
	}

	private static boolean isMeleeWeapon(int itemId)
	{
		switch (itemId)
		{
			case ItemID.GAUNTLET_MELEE_T1:
			case ItemID.GAUNTLET_MELEE_T2:
			case ItemID.GAUNTLET_MELEE_T3:
			case ItemID.GAUNTLET_MELEE_T1_HM:
			case ItemID.GAUNTLET_MELEE_T2_HM:
			case ItemID.GAUNTLET_MELEE_T3_HM:
				return true;
			default:
				return false;
		}
	}

	private static boolean isRangedWeapon(int itemId)
	{
		switch (itemId)
		{
			case ItemID.GAUNTLET_RANGED_T1:
			case ItemID.GAUNTLET_RANGED_T2:
			case ItemID.GAUNTLET_RANGED_T3:
			case ItemID.GAUNTLET_RANGED_T1_HM:
			case ItemID.GAUNTLET_RANGED_T2_HM:
			case ItemID.GAUNTLET_RANGED_T3_HM:
				return true;
			default:
				return false;
		}
	}

	private static ItemCombatStats statsFor(int itemId)
	{
		switch (itemId)
		{
			// Basic helms
			case ItemID.GAUNTLET_HELMET_T1:
			case ItemID.GAUNTLET_HELMET_T1_HM:
				return stats(2, 2, 1, 2, 2, 0, 0, 28, 1);
			// Attuned helms
			case ItemID.GAUNTLET_HELMET_T2:
			case ItemID.GAUNTLET_HELMET_T2_HM:
				return stats(6, 6, 2, 6, 6, 0, 0, 48, 2);
